/* ---- DHCP payload builder (real BOOTP layout, magic cookie, options) ---- */
function dhcpBytes(op, type, o){
  const b = new Array(240).fill(0), xid = [0x3a, 0x7c, 0x19, 0xe2], mac = [0x3c, 0x22, 0xfb, 0xa1, 0x09, 0x23];
  b[0] = op; b[1] = 1; b[2] = 6; b[3] = 0; xid.forEach((v, i) => { b[4 + i] = v; });
  if (op === 1) b[10] = 0x80;
  (o.yi || [0, 0, 0, 0]).forEach((v, i) => { b[16 + i] = v; }); (o.si || [0, 0, 0, 0]).forEach((v, i) => { b[20 + i] = v; }); (o.gi || [0, 0, 0, 0]).forEach((v, i) => { b[24 + i] = v; });
  mac.forEach((v, i) => { b[28 + i] = v; }); [99, 130, 83, 99].forEach((v, i) => { b[236 + i] = v; });
  const opt = [53, 1, type]; if (op === 1) opt.push(55, 3, 1, 3, 6); else opt.push(1, 4, 255, 255, 255, 0, 3, 4, ...(o.rt || [0, 0, 0, 0]), 6, 4, 192, 168, 20, 2, 51, 4, 0, 1, 81, 128);
  return b.concat(opt, [255]);
}
const DHCP_DISC = dhcpBytes(1, 1, {}), DHCP_DISC_RELAY = dhcpBytes(1, 1, {gi:[192, 168, 20, 1]}), DHCP_OFFER = dhcpBytes(2, 2, {yi:[192, 168, 20, 77], si:[192, 168, 20, 2], gi:[192, 168, 20, 1], rt:[192, 168, 20, 1]});
const QUIC_INIT = [0xc3, 0, 0, 0, 1, 8, 0x83, 0x94, 0xc8, 0xf0, 0x3e, 0x51, 0x57, 0x08, 0, 0, 0x44, 0x20, ...new Array(44).fill(0x5a)];
const QUIC_REPLY = [0xc3, 0, 0, 0, 1, 0, 8, 0xf0, 0x67, 0xa5, 0x50, 0x2a, 0x42, 0x62, 0xb5, 0, 0x44, 0x20, ...new Array(44).fill(0x3c)];

