  N('Server', 'SRV', 'server', 'AS 64510', 'DELIVERED', 17, '203.0.113.80', 'The server is reachable once a valid path exists end to end. The reply may use a different path (asymmetric routing), which is normal in BGP.', {docs:['rfc4271']})
